try:
    parse_duration('1h30')
except ValueError:
    pass
else:
    raise AssertionError('number without unit should raise ValueError')

try:
    parse_duration('abc')
except ValueError:
    pass
else:
    raise AssertionError('garbage should raise ValueError')

